import static org.junit.Assert.*;

public class ZipArchiveEntry_equals_TriageGen2Test {

    @Test
    public void testEquals_Reflexive() throws Exception {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertTrue(entry.equals(entry));
    }

    @Test
    public void testEquals_Null() throws Exception {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertFalse(entry.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() throws Exception {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertFalse(entry.equals("a string"));
    }

    @Test
    public void testEquals_SameContent() throws Exception {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        entry1.setComment("comment");
        entry1.setSize(100L);
        entry1.setMethod(0);
        entry1.setInternalAttributes(1);
        entry1.setExternalAttributes(2L);
        entry1.setCentralDirectoryExtra(new byte[]{1, 2});
        entry1.setLocalFileDataExtra(new byte[]{3, 4});
        // Note: gpb is internal, but we assume default state is equal

        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        entry2.setComment("comment");
        entry2.setSize(100L);
        entry2.setMethod(0);
        entry2.setInternalAttributes(1);
        entry2.setExternalAttributes(2L);
        entry2.setCentralDirectoryExtra(new byte[]{1, 2});
        entry2.setLocalFileDataExtra(new byte[]{3, 4});

        assertTrue(entry1.equals(entry2));
    }

    @Test
    public void testEquals_DifferentName() throws Exception {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("a.txt");
        ZipArchiveEntry entry2 = new ZipArchiveEntry("b.txt");
        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_NullName_DifferentOtherName() throws Exception {
        // Using reflection or a way to set name to null if possible, 
        // but since name is usually set in constructor, we rely on logic
        // In this implementation, name is a String. 
        // We simulate the null logic branches.
        ZipArchiveEntry entry1 = new ZipArchiveEntry((String) null);
        ZipArchiveEntry entry2 = new ZipArchiveEntry("not-null");
        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_BothNullName() throws Exception {
        ZipArchiveEntry entry1 = new ZipArchiveEntry((String) null);
        ZipArchiveEntry entry2 = new ZipArchiveEntry((String) null);
        assertTrue(entry1.equals(entry2));
    }

    @Test
    public void testEquals_DifferentComment() throws Exception {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        entry1.setComment("c1");
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        entry2.setComment("c2");
        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_NullComment_DifferentOtherComment() throws Exception {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        // entry1 comment is null by default
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        entry2.setComment("c1");
        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_BothNullComment() throws Exception {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
