    @Test
    public void testEquals_MismatchPlatform() throws Exception {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        // Platform is protected, but set via platform-specific logic usually
        // We test the equality branch of the primitive comparison
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        // Assuming default platform is 0
        assertTrue(entry1.equals(entry2));
